void jas_free(void *ptr) /* <=== jas_free */ 
{
	JAS_DBGLOG(100, ("jas_free(%p)\n", ptr));
	free(ptr);
}

inline static bool jas_safe_size_mul(size_t x, size_t y, size_t *result) /* <=== jas_safe_size_mul */ 
{
	/* Check if overflow would occur */
	if (x && y > SIZE_MAX / x) {
		/* Overflow would occur. */
		return false;
	}
	*result = x * y;
	return true;
}

jpc_pchglist_t *jpc_pchglist_create() /* <=== jpc_pchglist_create */ 
{
	jpc_pchglist_t *pchglist;
	if (!(pchglist = jas_malloc(sizeof(jpc_pchglist_t)))) {
		return 0;
	}
	pchglist->numpchgs = 0;
	pchglist->maxpchgs = 0;
	pchglist->pchgs = 0;
	return pchglist;
}

static void jpc_dec_cp_destroy(jpc_dec_cp_t *cp) /* <=== jpc_dec_cp_destroy */ 
{
	if (cp->ccps) {
		jas_free(cp->ccps);
	}
	if (cp->pchglist) {
		jpc_pchglist_destroy(cp->pchglist);
	}
	jas_free(cp);
}

void jpc_pchglist_destroy(jpc_pchglist_t *pchglist) /* <=== jpc_pchglist_destroy */ 
{
	int pchgno;
	if (pchglist->pchgs) {
		for (pchgno = 0; pchgno < pchglist->numpchgs; ++pchgno) {
			jpc_pchg_destroy(pchglist->pchgs[pchgno]);
		}
		jas_free(pchglist->pchgs);
	}
	jas_free(pchglist);
}

void *jas_alloc2(size_t num_elements, size_t element_size) /* <=== jas_alloc2 */ 
{
	size_t size;
	if (!jas_safe_size_mul(num_elements, element_size, &size)) {
		return 0;
	}
	return jas_malloc(size);
}

void *jas_malloc(size_t size) /* <=== jas_malloc */ 
{
	void *result;
	JAS_DBGLOG(101, ("jas_malloc(%zu)\n", size));
	result = malloc(size);
	JAS_DBGLOG(100, ("jas_malloc(%zu) -> %p\n", size, result));
	return result;
}

inline static bool jas_safe_size_mul(size_t x, size_t y, size_t *result) /* <=== jas_safe_size_mul */ 
{
	/* Check if overflow would occur */
	if (x && y > SIZE_MAX / x) {
		/* Overflow would occur. */
